1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.Regiao;
4	import com.loja.checkout.domain.clube.*;
5	import com.loja.checkout.domain.cupom.*;
6	import com.loja.checkout.domain.modalidade.*;
7	import com.loja.checkout.domain.pagamento.*;
8	import com.loja.checkout.dto.ItemCarrinho;
9	import com.loja.checkout.dto.PedidoRequest;
10	import com.loja.checkout.dto.ResumoResponse;
11	import com.loja.checkout.exception.CheckoutException;
12	import com.loja.checkout.exception.CodigoErro;
13	import org.springframework.stereotype.Service;
14	
15	import java.math.BigDecimal;
16	import java.math.RoundingMode;
17	import java.util.List;
18	import java.util.Map;
19	
20	@Service
21	public class CalculadoraResumoService {
22	    private final Map<String, ModalidadeEntrega> modalidades = Map.of(
23	        "ECONOMICA", new Economica(),
24	        "EXPRESSA", new Expressa(),
25	        "RETIRADA_LOJA", new RetiradaLoja(),
26	        "MOTOBOY", new Motoboy()
27	    );
28	
29	    private final Map<String, Cupom> cupons = Map.of(
30	        "BEMVINDO10", new BemVindo10(),
31	        "MENOS50", new Menos50(),
32	        "FRETEGRATIS", new FreteGratis(),
33	        "LEVE3PAGUE2", new Leve3Pague2()
34	    );
35	
36	    private final Map<String, NivelClube> niveisClube = Map.of(
37	        "BRONZE", new Bronze(),
38	        "PRATA", new Prata(),
39	        "OURO", new Ouro()
40	    );
41	
42	    private final Map<String, FormaPagamento> formasPagamento = Map.of(
43	        "PIX", new Pix(),
44	        "CARTAO", new Cartao(),
45	        "BOLETO", new Boleto()
46	    );
47	
48	    public ResumoResponse calcular(PedidoRequest pedido) {
49	        validarPedido(pedido);
50	
51	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(pedido.itens());
52	
53	        NivelClube nivelClube = obterNivelClube(pedido.nivelClube());
54	        ModalidadeEntrega modalidade = obterModalidade(pedido.modalidadeEntrega());
55	
56	        BigDecimal freteOriginal = modalidade.calcularFrete(pedido.itens());
57	        BigDecimal frete = nivelClube.zeraFrete() ? BigDecimal.ZERO.setScale(2) : freteOriginal;
58	
59	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
60	        if (pedido.cupom() != null && !pedido.cupom().isBlank()) {
61	            Cupom cupom = obterCupom(pedido.cupom());
62	            descontoCupom = cupom.calcularDesconto(subtotalProdutos, freteOriginal, pedido.itens());
63	        }
64	
65	        Regiao regiao = obterRegiao(pedido.regiao());
66	        BigDecimal seguro = subtotalProdutos.multiply(regiao.getPercentualSeguro())
67	            .setScale(2, RoundingMode.HALF_EVEN);
68	
69	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
70	
71	        FormaPagamento formaPagamento = obterFormaPagamento(pedido.formaPagamento());
72	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
73	
74	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
75	        BigDecimal totalFinal = totalPedido.add(ajustePagamento);
76	        BigDecimal valorParcela = formaPagamento.calcularValorParcela(totalPedido, parcelas);
77	
78	        BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
79	        boolean brinde = nivelClube.ganhaBrinde(subtotalProdutos);
80	
81	        return new ResumoResponse(
82	            subtotalProdutos,
83	            descontoCupom,
84	            frete,
85	            modalidade.obterPrazoDias(),
86	            seguro,
87	            ajustePagamento,
88	            totalFinal,
89	            parcelas,
90	            valorParcela,
91	            creditoProximaCompra,
92	            brinde
93	        );
94	    }
95	
96	    private void validarPedido(PedidoRequest pedido) {
97	        // 1. PEDIDO_INVALIDO
98	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
99	            throw new CheckoutException(CodigoErro.PEDIDO_INVALIDO);
100	        }
101	        for (ItemCarrinho item : pedido.itens()) {
102	            if (item.precoUnitario() == null || item.precoUnitario() <= 0 ||
103	                item.quantidade() == null || item.quantidade() <= 0 ||
104	                item.pesoKg() == null || item.pesoKg() <= 0) {
105	                throw new CheckoutException(CodigoErro.PEDIDO_INVALIDO);
106	            }
107	        }
108	
109	        // 2. NIVEL_CLUBE_INVALIDO
110	        if (pedido.nivelClube() == null || !niveisClube.containsKey(pedido.nivelClube())) {
111	            throw new CheckoutException(CodigoErro.NIVEL_CLUBE_INVALIDO);
112	        }
113	
114	        // 3. REGIAO_INVALIDA
115	        try {
116	            if (pedido.regiao() == null) {
117	                throw new CheckoutException(CodigoErro.REGIAO_INVALIDA);
118	            }
119	            Regiao.valueOf(pedido.regiao());
120	        } catch (IllegalArgumentException e) {
121	            throw new CheckoutException(CodigoErro.REGIAO_INVALIDA);
122	        }
123	
124	        // 4. MODALIDADE_INVALIDA
125	        if (pedido.modalidadeEntrega() == null || !modalidades.containsKey(pedido.modalidadeEntrega())) {
126	            throw new CheckoutException(CodigoErro.MODALIDADE_INVALIDA);
127	        }
128	
129	        // 5. MODALIDADE_INDISPONIVEL
130	        ModalidadeEntrega modalidade = modalidades.get(pedido.modalidadeEntrega());
131	        if (!modalidade.aceitaPedido(pedido.itens())) {
132	            throw new CheckoutException(CodigoErro.MODALIDADE_INDISPONIVEL);
133	        }
134	
135	        // 6. CUPOM_INVALIDO
136	        if (pedido.cupom() != null && !pedido.cupom().isBlank()) {
137	            if (!cupons.containsKey(pedido.cupom())) {
138	                throw new CheckoutException(CodigoErro.CUPOM_INVALIDO);
139	            }
140	
141	            // 7. CUPOM_NAO_APLICAVEL
142	            Cupom cupom = cupons.get(pedido.cupom());
143	            BigDecimal subtotalProdutos = calcularSubtotalProdutos(pedido.itens());
144	            if (!cupom.aplicavel(subtotalProdutos, pedido.itens())) {
145	                throw new CheckoutException(CodigoErro.CUPOM_NAO_APLICAVEL);
146	            }
147	        }
148	
149	        // 8. FORMA_PAGAMENTO_INVALIDA
150	        if (pedido.formaPagamento() == null || !formasPagamento.containsKey(pedido.formaPagamento())) {
151	            throw new CheckoutException(CodigoErro.FORMA_PAGAMENTO_INVALIDA);
152	        }
153	
154	        FormaPagamento formaPagamento = formasPagamento.get(pedido.formaPagamento());
155	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
156	
157	        // 9. PARCELAMENTO_INVALIDO
158	        if (!formaPagamento.aceitaParcelas(parcelas)) {
159	            throw new CheckoutException(CodigoErro.PARCELAMENTO_INVALIDO);
160	        }
161	
162	        // 10. FORMA_PAGAMENTO_INDISPONIVEL
163	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(pedido.itens());
164	        NivelClube nivelClube = niveisClube.get(pedido.nivelClube());
165	        BigDecimal freteOriginal = modalidade.calcularFrete(pedido.itens());
166	        BigDecimal frete = nivelClube.zeraFrete() ? BigDecimal.ZERO.setScale(2) : freteOriginal;
167	
168	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
169	        if (pedido.cupom() != null && !pedido.cupom().isBlank()) {
170	            Cupom cupom = cupons.get(pedido.cupom());
171	            descontoCupom = cupom.calcularDesconto(subtotalProdutos, freteOriginal, pedido.itens());
172	        }
173	
174	        Regiao regiao = Regiao.valueOf(pedido.regiao());
175	        BigDecimal seguro = subtotalProdutos.multiply(regiao.getPercentualSeguro())
176	            .setScale(2, RoundingMode.HALF_EVEN);
177	
178	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
179	
180	        if (!formaPagamento.aceitaPedido(totalPedido)) {
181	            throw new CheckoutException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
182	        }
183	    }
184	
185	    private BigDecimal calcularSubtotalProdutos(List<ItemCarrinho> itens) {
186	        BigDecimal subtotal = BigDecimal.ZERO;
187	        for (ItemCarrinho item : itens) {
188	            BigDecimal totalItem = BigDecimal.valueOf(item.precoUnitario())
189	                .multiply(BigDecimal.valueOf(item.quantidade()));
190	            subtotal = subtotal.add(totalItem);
191	        }
192	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
193	    }
194	
195	    private NivelClube obterNivelClube(String nivel) {
196	        return niveisClube.get(nivel);
197	    }
198	
199	    private ModalidadeEntrega obterModalidade(String modalidade) {
200	        return modalidades.get(modalidade);
201	    }
202	
203	    private Cupom obterCupom(String codigo) {
204	        return cupons.get(codigo);
205	    }
206	
207	    private Regiao obterRegiao(String regiao) {
208	        return Regiao.valueOf(regiao);
209	    }
210	
211	    private FormaPagamento obterFormaPagamento(String forma) {
212	        return formasPagamento.get(forma);
213	    }
214	}
