1	package com.loja.checkout.domain.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public class Cartao implements FormaPagamento {
7	    private static final BigDecimal TAXA_JUROS_MENSAL = new BigDecimal("0.0199");
8	
9	    @Override
10	    public boolean aceitaPedido(BigDecimal totalPedido) {
11	        return true;
12	    }
13	
14	    @Override
15	    public boolean aceitaParcelas(int parcelas) {
16	        return parcelas >= 1 && parcelas <= 12;
17	    }
18	
19	    @Override
20	    public BigDecimal calcularAjuste(BigDecimal totalPedido, int parcelas) {
21	        BigDecimal totalFinal = calcularTotalFinal(totalPedido, parcelas);
22	        return totalFinal.subtract(totalPedido);
23	    }
24	
25	    @Override
26	    public BigDecimal calcularValorParcela(BigDecimal totalPedido, int parcelas) {
27	        if (parcelas <= 3) {
28	            return totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
29	        }
30	
31	        // Tabela Price: parcela = total × taxa ÷ (1 − (1 + taxa)^−parcelas)
32	        BigDecimal taxa = TAXA_JUROS_MENSAL;
33	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);
34	        BigDecimal denominador = BigDecimal.ONE.subtract(
35	            BigDecimal.ONE.divide(umMaisTaxa.pow(parcelas), 10, RoundingMode.HALF_EVEN)
36	        );
37	
38	        BigDecimal valorParcela = totalPedido.multiply(taxa)
39	            .divide(denominador, 2, RoundingMode.HALF_EVEN);
40	
41	        return valorParcela;
42	    }
43	
44	    private BigDecimal calcularTotalFinal(BigDecimal totalPedido, int parcelas) {
45	        if (parcelas <= 3) {
46	            return totalPedido;
47	        }
48	
49	        BigDecimal valorParcela = calcularValorParcela(totalPedido, parcelas);
50	        return valorParcela.multiply(BigDecimal.valueOf(parcelas));
51	    }
52	}
