public ResumoResponse calcular(PedidoRequest pedido) {
    validarPedido(pedido);

    BigDecimal subtotalProdutos = calcularSubtotalProdutos(pedido.itens());

    NivelClube nivelClube = obterNivelClube(pedido.nivelClube());
    ModalidadeEntrega modalidade = obterModalidade(pedido.modalidadeEntrega());

    BigDecimal freteOriginal = modalidade.calcularFrete(pedido.itens());
    BigDecimal frete = nivelClube.zeraFrete() ? BigDecimal.ZERO.setScale(2) : freteOriginal;

    BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
    if (pedido.cupom() != null && !pedido.cupom().isBlank()) {
        Cupom cupom = obterCupom(pedido.cupom());
        descontoCupom = cupom.calcularDesconto(subtotalProdutos, freteOriginal, pedido.itens());
    }

    Regiao regiao = obterRegiao(pedido.regiao());
    BigDecimal seguro = subtotalProdutos.multiply(regiao.getPercentualSeguro())
        .setScale(2, RoundingMode.HALF_EVEN);

    BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);

    FormaPagamento formaPagamento = obterFormaPagamento(pedido.formaPagamento());
    int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;

    BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
    BigDecimal totalFinal = totalPedido.add(ajustePagamento);
    BigDecimal valorParcela = formaPagamento.calcularValorParcela(totalPedido, parcelas);

    BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
    boolean brinde = nivelClube.ganhaBrinde(subtotalProdutos);

    return new ResumoResponse(
        subtotalProdutos,
        descontoCupom,
        frete,
        modalidade.obterPrazoDias(),
        seguro,
        ajustePagamento,
        totalFinal,
        parcelas,
        valorParcela,
        creditoProximaCompra,
        brinde
    );
}

